/* AI TEACHER DEDUPE 1.0.0
 * Keep the canonical AI cards from index.html.
 * Remove only the duplicate cards generated by ui-complete-fix.js.
 */
(function(){
  'use strict';
  if(window.__LH_AI_TEACHER_DEDUPE__) return;
  window.__LH_AI_TEACHER_DEDUPE__=true;

  function clean(){
    const page=document.getElementById('page-ai');
    if(!page) return;
    page.querySelectorAll(':scope > .ui-complete-page').forEach(el=>el.remove());
    page.querySelectorAll('.ui-complete-page').forEach(el=>el.remove());
    const legacy=page.querySelector('.ui-complete-grid');
    if(legacy) legacy.closest('.ui-complete-page')?.remove();
  }

  function install(){
    clean();
    const page=document.getElementById('page-ai');
    if(!page) return;
    if(window.__LH_AI_TEACHER_DEDUPE_OBSERVER__) return;
    const observer=new MutationObserver(()=>{
      let changed=false;
      page.querySelectorAll('.ui-complete-page').forEach(el=>{el.remove(); changed=true;});
      if(changed) return;
    });
    observer.observe(page,{childList:true,subtree:true});
    window.__LH_AI_TEACHER_DEDUPE_OBSERVER__=observer;
  }

  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',install,{once:true});
  }else{
    install();
  }
})();
